"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type GlyphSparkProps = {
  text: string;
  className?: string;
  /** Characters per second when auto-playing */
  speed?: number;
  playing?: boolean;
};

/**
 * Type-out display where each revealed glyph emits a tiny spark.
 */
function GlyphSpark({
  text,
  className,
  speed = 18,
  playing = true,
}: GlyphSparkProps) {
  const [count, setCount] = React.useState(playing ? 0 : text.length);
  const [sparks, setSparks] = React.useState<
    { id: number; i: number; x: number; y: number }[]
  >([]);

  React.useEffect(() => {
    if (!playing) {
      setCount(text.length);
      return;
    }
    setCount(0);
    const id = window.setInterval(() => {
      setCount((c) => {
        if (c >= text.length) {
          window.clearInterval(id);
          return c;
        }
        const next = c + 1;
        setSparks((s) => [
          ...s.slice(-12),
          {
            id: Date.now() + next,
            i: next - 1,
            x: (Math.random() - 0.5) * 16,
            y: -10 - Math.random() * 12,
          },
        ]);
        return next;
      });
    }, 1000 / speed);
    return () => window.clearInterval(id);
  }, [text, speed, playing]);

  return (
    <div className={cn("relative inline-block font-semibold tracking-tight", className)}>
      <span className="relative">
        {text.slice(0, count).split("").map((ch, i) => (
          <span key={`${i}-${ch}`} className="relative inline-block">
            {ch === " " ? "\u00A0" : ch}
            {sparks
              .filter((s) => s.i === i)
              .map((s) => (
                <span
                  key={s.id}
                  aria-hidden
                  className="pointer-events-none absolute left-1/2 top-0 size-1.5 -translate-x-1/2 rounded-full bg-primary animate-[joy-spark_0.55s_ease-out_forwards]"
                  style={
                    {
                      "--joy-spark-x": `${s.x}px`,
                      "--joy-spark-y": `${s.y}px`,
                    } as React.CSSProperties
                  }
                />
              ))}
          </span>
        ))}
        {playing && count < text.length ? (
          <span className="ml-0.5 inline-block h-[1em] w-[2px] animate-pulse bg-primary align-[-0.1em]" />
        ) : null}
      </span>
    </div>
  );
}

export { GlyphSpark };
